import React, { useEffect, useState } from 'react';

export default function AdBanner() {
  const [banners, setBanners] = useState([]);
  const [index, setIndex]     = useState(0);
  const [sliding, setSliding] = useState(false);

  useEffect(() => {
    fetch('http://localhost:5000/api/banners/current')
      .then(r => r.json())
      .then(data => { if (data.banners?.length) setBanners(data.banners); })
      .catch(() => {});
  }, []);

  // Auto-advance every 3s
  useEffect(() => {
    if (banners.length <= 1) return;
    const t = setInterval(() => {
      setSliding(true);
      setTimeout(() => {
        setIndex(i => (i + 1) % banners.length);
        setSliding(false);
      }, 500); // matches transition duration
    }, 3000);
    return () => clearInterval(t);
  }, [banners]);

  if (!banners.length) return null;

  return (
    <div style={wrapper}>
      <style>{`
        .ad-slide-enter  { transform: translateX(100%); }
        .ad-slide-active { transform: translateX(0);    transition: transform 0.5s ease; }
        .ad-slide-exit   { transform: translateX(-100%); transition: transform 0.5s ease; }
      `}</style>

      <div style={inner}>
        {banners.map((b, i) => (
          <img
            key={b.url}
            src={b.url}
            alt=""
            style={{
              ...imgStyle,
              opacity:    i === index ? 1 : 0,
              transform:  i === index
                ? sliding ? 'translateX(-100%)' : 'translateX(0)'
                : i === (index + 1) % banners.length ? 'translateX(100%)' : 'translateX(100%)',
              transition: 'transform 0.5s ease, opacity 0.5s ease',
            }}
          />
        ))}

        {/* Dot indicators */}
        {banners.length > 1 && (
          <div style={dots}>
            {banners.map((_, i) => (
              <div key={i} onClick={() => setIndex(i)} style={{
                width: i === index ? 20 : 7, height: 7,
                borderRadius: 4,
                background: i === index ? '#f97316' : 'rgba(255,255,255,0.4)',
                cursor: 'pointer',
                transition: 'width 0.3s, background 0.3s',
              }} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

const wrapper = {
  width: '100%',
  background: '#000',
  borderBottom: '1px solid #1a1a1a',
  display: 'flex',
  justifyContent: 'center',
  padding: '12px 0 20px',
};

const imgStyle = {
  position: 'absolute',
  inset: 0,
  width: '100%',
  height: '100%',
  objectFit: 'contain',
  objectPosition: 'center',
  display: 'block',
  userSelect: 'none',
  pointerEvents: 'none',
};

const inner = {
  position: 'relative',
  width: '100%',
  maxWidth: 480,
  height: 260,
  overflow: 'hidden',
  borderRadius: 12,
  background: '#111',
};

const dots = {
  position: 'absolute',
  bottom: 12,
  left: '50%',
  transform: 'translateX(-50%)',
  display: 'flex',
  gap: 6,
  alignItems: 'center',
};
